var metricsAggregator = require("./MetricsAggregator");
class GcMetricsAggregator extends metricsAggregator {
  constructor() {
    super();
  }

  addToExistingMetricData(stats) {
    super.addToExistingMetricData(stats);
    this.sum += stats.pauseMS;
    this.max = stats.pauseMS > this.max ? stats.pauseMS : this.max;
    this.min = stats.pauseMS < this.min ? stats.pauseMS : this.min;
  }
}
module.exports = GcMetricsAggregator;
